$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Windows.Forms
$AppName = 'TeslaPro SS Tool'
$DiscordInvite = 'https://discord.gg/sFn5TvpAK6'
$BasePath = if ([string]::IsNullOrWhiteSpace($PSScriptRoot)) { (Get-Location).Path } else { $PSScriptRoot }
$ToolsPath = Join-Path $BasePath 'tools'
$HtmlBase64 = ''

function Get-FreePort {
    $listener = [System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback, 0)
    $listener.Start()
    $port = ([System.Net.IPEndPoint]$listener.LocalEndpoint).Port
    $listener.Stop()
    return $port
}

function Send-Response {
    param(
        [Parameter(Mandatory)]$Context,
        [Parameter(Mandatory)][byte[]]$Bytes,
        [string]$ContentType = 'application/json; charset=utf-8',
        [int]$StatusCode = 200
    )
    $Context.Response.StatusCode = $StatusCode
    $Context.Response.ContentType = $ContentType
    $Context.Response.ContentLength64 = $Bytes.Length
    $Context.Response.OutputStream.Write($Bytes, 0, $Bytes.Length)
    $Context.Response.OutputStream.Close()
}

function Send-Json {
    param($Context, $Object, [int]$StatusCode = 200)
    $json = $Object | ConvertTo-Json -Depth 12 -Compress
    Send-Response -Context $Context -Bytes ([Text.Encoding]::UTF8.GetBytes($json)) -StatusCode $StatusCode
}

function Get-SafeName {
    param([string]$Name)
    foreach ($char in [IO.Path]::GetInvalidFileNameChars()) { $Name = $Name.Replace([string]$char, '_') }
    return $Name
}

function Download-TeslaTool {
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][object[]]$Urls,
        [Parameter(Mandatory)][string]$Category
    )

    $safeCategory = Get-SafeName $Category
    $categoryPath = Join-Path $ToolsPath $safeCategory
    [IO.Directory]::CreateDirectory($categoryPath) | Out-Null

    $firstUrl = [string]$Urls[0]
    $firstUri = [Uri]$firstUrl
    $extension = [IO.Path]::GetExtension($firstUri.AbsolutePath)
    if ([string]::IsNullOrWhiteSpace($extension)) { $extension = '.exe' }
    $primaryPath = Join-Path $categoryPath ((Get-SafeName $Name) + $extension)

    for ($i = 0; $i -lt $Urls.Count; $i++) {
        $url = [string]$Urls[$i]
        $uri = [Uri]$url
        $destination = if ($i -eq 0) { $primaryPath } else { Join-Path $categoryPath (Get-SafeName ([IO.Path]::GetFileName($uri.AbsolutePath))) }
        $temporary = "$destination.tmp"
        try {
            Invoke-WebRequest -Uri $url -OutFile $temporary -UseBasicParsing -MaximumRedirection 10
            Move-Item -LiteralPath $temporary -Destination $destination -Force
        }
        catch {
            Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue
            throw
        }
    }

    $isZip = [IO.Path]::GetExtension($primaryPath).Equals('.zip', [StringComparison]::OrdinalIgnoreCase)
    if (-not $isZip) { Start-Process -FilePath $primaryPath -WorkingDirectory (Split-Path $primaryPath) }

    return [ordered]@{
        type = 'downloadComplete'
        name = $Name
        success = $true
        exePath = $primaryPath
        isZip = $isZip
    }
}

function Handle-ApiRequest {
    param($Context)
    try {
        $reader = [IO.StreamReader]::new($Context.Request.InputStream, $Context.Request.ContentEncoding)
        try { $payload = $reader.ReadToEnd() | ConvertFrom-Json } finally { $reader.Dispose() }
        $method = [string]$payload.method
        $args = @($payload.args)

        switch ($method) {
            'downloadTool' {
                $name = [string]$args[0]
                $urls = @(([string]$args[1] | ConvertFrom-Json))
                $category = [string]$args[2]
                $result = Download-TeslaTool -Name $name -Urls $urls -Category $category
                Send-Json $Context $result
            }
            'launchTool' {
                $path = [IO.Path]::GetFullPath([string]$args[0])
                $root = [IO.Path]::GetFullPath($ToolsPath) + [IO.Path]::DirectorySeparatorChar
                if (-not $path.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) { throw 'Blocked path outside the tools directory.' }
                Start-Process -FilePath $path -WorkingDirectory (Split-Path $path)
                Send-Json $Context @{ ok = $true }
            }
            'openScript' {
                $command = [string]$args[0]
                $encoded = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($command))
                Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-EncodedCommand',$encoded)
                Send-Json $Context @{ ok = $true }
            }
            'openDiscord' {
                Start-Process $DiscordInvite
                Send-Json $Context @{ ok = $true }
            }
            'cancelDownload' { Send-Json $Context @{ ok = $true } }
            default { Send-Json $Context @{ error = 'Unknown method.' } 400 }
        }
    }
    catch {
        $name = if ($payload -and $payload.args -and $payload.args.Count -gt 0) { [string]$payload.args[0] } else { 'Tool' }
        Send-Json $Context @{ type='downloadComplete'; name=$name; success=$false; error=$_.Exception.Message } 500
    }
}

[IO.Directory]::CreateDirectory($ToolsPath) | Out-Null
$htmlBytes = [Convert]::FromBase64String($HtmlBase64)
$port = Get-FreePort
$prefix = "http://127.0.0.1:$port/"
$listener = [Net.HttpListener]::new()
$listener.Prefixes.Add($prefix)

try {
    $listener.Start()

    $edgeCandidates = @(
        (Join-Path ${env:ProgramFiles(x86)} 'Microsoft\Edge\Application\msedge.exe'),
        (Join-Path $env:ProgramFiles 'Microsoft\Edge\Application\msedge.exe')
    ) | Where-Object { $_ -and (Test-Path $_) }

    if ($edgeCandidates.Count -gt 0) {
        $edge = $edgeCandidates[0]
        $edgeProcess = Start-Process -FilePath $edge -ArgumentList @("--app=$prefix", '--new-window', '--disable-features=msEdgeSidebarV2') -PassThru
    } else {
        Start-Process $prefix
        $edgeProcess = $null
    }

    while ($listener.IsListening) {
        if ($edgeProcess -and $edgeProcess.HasExited) { break }
        $context = $listener.GetContext()
        $path = $context.Request.Url.AbsolutePath
        if ($context.Request.HttpMethod -eq 'GET' -and ($path -eq '/' -or $path -eq '/index.html')) {
            Send-Response -Context $context -Bytes $htmlBytes -ContentType 'text/html; charset=utf-8'
        }
        elseif ($context.Request.HttpMethod -eq 'POST' -and $path -eq '/api') {
            Handle-ApiRequest $context
        }
        elseif ($path -eq '/favicon.ico') {
            Send-Response -Context $context -Bytes ([byte[]]@()) -ContentType 'image/x-icon' -StatusCode 204
        }
        else {
            Send-Response -Context $context -Bytes ([Text.Encoding]::UTF8.GetBytes('Not found')) -ContentType 'text/plain; charset=utf-8' -StatusCode 404
        }
    }
}
catch {
    [Windows.Forms.MessageBox]::Show("$AppName failed to start.`n`n$($_.Exception.Message)", $AppName, 'OK', 'Error') | Out-Null
}
finally {
    if ($listener.IsListening) { $listener.Stop() }
    $listener.Close()
}
